    function run(uint amount1, uint amount2) public payable {
        require(address(this).balance >= amount1 + amount2);

        // Initial balance should be zero for a fresh contract
        uint initialBal = c.getBalance(address(this));
        require(initialBal == 0);

        // First deposit
        c.addToBalance{value: amount1}();
        uint balAfterFirst = c.getBalance(address(this));

        // Second deposit
        c.addToBalance{value: amount2}();
        uint balAfterSecond = c.getBalance(address(this));

        // Rule: the recorded balance is the sum of successful deposits.
        // Since initialBal == 0, balAfterFirst == amount1 and balAfterSecond == amount1 + amount2.
        assert(balAfterFirst == amount1 && balAfterSecond == amount1 + amount2);
    }

    receive() external payable {}
}

